/**
 * Role Route Resolver & Dashboard Isolation Utility
 * Maps all 14 Zibonbaba system roles to their exact dedicated dashboard routes.
 */

export function getDashboardForRole(role?: string | null): string {
  if (!role) return '/login';

  const normalized = role.trim().toUpperCase();

  switch (normalized) {
    case 'SUPER_ADMIN':
      return '/superadmin';
    case 'ADMIN':
    case 'MARKETING':
      return '/admin';
    case 'MANAGER':
      return '/staff/manager';
    case 'ACCOUNTANT':
      return '/staff/accountant';
    case 'CUSTOMER_SUPPORT':
    case 'SUPPORT':
      return '/staff/support';
    case 'WAREHOUSE_MANAGER':
    case 'INVENTORY_MANAGER':
      return '/staff/warehouse';
    case 'DELIVERY_MANAGER':
      return '/staff/delivery';
    case 'VENDOR_ADMIN':
    case 'SELLER':
    case 'VENDOR':
      return '/seller';
    case 'VENDOR_STAFF':
      return '/seller/staff';
    case 'RESELLER':
      return '/reseller';
    case 'DELIVERY_MAN':
    case 'COURIER':
      return '/delivery';
    case 'CUSTOMER':
      return '/';
    default:
      return '/';
  }
}

/**
 * Returns true if the user is a non-customer staff/admin/vendor/courier/reseller
 * who should be restricted from viewing the customer shopping interface.
 */
export function isNonCustomerRole(role?: string | null): boolean {
  if (!role) return false;
  const normalized = role.trim().toUpperCase();
  return normalized !== 'CUSTOMER';
}

/**
 * Returns true if the given pathname is part of the customer shopping interface.
 */
export function isCustomerInterfaceRoute(pathname: string): boolean {
  if (!pathname) return false;

  // Exact homepage or customer storefront paths
  if (pathname === '/') return true;

  const customerPrefixes = [
    '/cart',
    '/checkout',
    '/product',
    '/wishlist',
    '/category',
    '/search',
    '/tracking'
  ];

  return customerPrefixes.some(prefix => pathname === prefix || pathname.startsWith(`${prefix}/`));
}

/**
 * Returns true if the given pathname belongs to an Admin, Seller, Superadmin, Staff, ERP, Delivery, or Reseller portal.
 */
export function isDashboardRoute(pathname: string): boolean {
  if (!pathname) return false;
  const dashboardPrefixes = [
    '/admin',
    '/superadmin',
    '/seller',
    '/staff',
    '/erp',
    '/delivery',
    '/reseller'
  ];
  return dashboardPrefixes.some(prefix => pathname === prefix || pathname.startsWith(`${prefix}/`));
}

/**
 * Determines whether the public website heading / header part (Navbar, MobileHeader, Footer)
 * should be hidden for admin/seller accounts or dashboard routes.
 */
export function shouldHideStorefrontHeader(pathname: string, role?: string | null, isLoggedIn?: boolean): boolean {
  if (isDashboardRoute(pathname)) return true;
  if (isLoggedIn && isNonCustomerRole(role)) return true;
  return false;
}

import { createBrowserClient } from '@supabase/ssr'

export function createClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
  )
}

import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { cookies } from 'next/headers'

export async function createClient() {
  const cookieStore = await cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // The `setAll` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing
            // user sessions.
          }
        },
      },
    }
  )
}

import { headers, cookies } from 'next/headers';
import { prisma } from '@/lib/prisma';
import jwt from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET || 'zibonbaba_super_secure_jwt_session_secret_token_123';

export interface AuthUser {
  id: string;
  email: string;
  role: string;
}

export interface SellerContext {
  user: AuthUser;
  store: {
    id: string;
    name: string;
    isApproved: boolean;
    commissionRate: number;
    ownerId: string;
  } | null;
  isPending: boolean;
}

/**
 * Extracts and verifies the JWT token from incoming Request headers or cookies.
 */
export async function getAuthUser(req?: Request): Promise<AuthUser | null> {
  let token: string | null = null;

  if (req) {
    const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
    if (authHeader && authHeader.startsWith('Bearer ')) {
      token = authHeader.substring(7).trim();
    }

    if (!token) {
      const cookieHeader = req.headers.get('cookie') || '';
      const match = cookieHeader.match(/zibonbaba_token=([^;]+)/);
      if (match) {
        token = decodeURIComponent(match[1]);
      }
    }
  }

  if (!token) {
    try {
      const cookieStore = await cookies();
      const cookieToken = cookieStore.get('zibonbaba_token')?.value;
      if (cookieToken) token = cookieToken;
    } catch (_) {}
  }

  if (!token) return null;

  try {
    const decoded = jwt.verify(token, JWT_SECRET) as any;
    if (decoded && decoded.id && decoded.email) {
      return {
        id: decoded.id,
        email: decoded.email,
        role: (decoded.role || 'CUSTOMER').toUpperCase()
      };
    }
  } catch (err) {
    return null;
  }

  return null;
}

/**
 * Ensures the authenticated user has one of the allowed administrative roles.
 */
export async function requireAdminRole(
  req?: Request,
  allowedRoles: string[] = ['SUPER_ADMIN', 'ADMIN']
): Promise<{ user: AuthUser | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { user: null, error: 'Authentication required. Please log in to the admin portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const normalizedAllowed = allowedRoles.map(r => r.toUpperCase());

  if (!normalizedAllowed.includes(normalizedRole)) {
    return {
      user,
      error: `Access Denied. Role '${user.role}' is not authorized for administrative access.`,
      status: 403
    };
  }

  return { user, error: null, status: 200 };
}

/**
 * Ensures the authenticated user is a Seller (VENDOR_ADMIN or VENDOR_STAFF)
 * and retrieves their associated store context.
 */
export async function requireSeller(
  req?: Request
): Promise<{ context: SellerContext | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { context: null, error: 'Authentication required. Please log in to the seller portal.', status: 401 };
  }

  const normalizedRole = user.role.toUpperCase();
  const sellerRoles = ['VENDOR_ADMIN', 'SELLER', 'VENDOR_STAFF', 'SUPER_ADMIN', 'ADMIN'];

  if (!sellerRoles.includes(normalizedRole)) {
    return {
      context: null,
      error: 'Access Denied. A seller account is required to access this resource.',
      status: 403
    };
  }

  // Find user's own store strictly by ownerId
  let store = await prisma.store.findFirst({
    where: { ownerId: user.id }
  });

  // If user is seller staff, find the store they belong to
  if (!store && normalizedRole === 'VENDOR_STAFF') {
    const staffMembership = await prisma.staffMember.findFirst({
      where: { userId: user.id, isActive: true },
      include: { seller: { include: { stores: true } } }
    });
    if (staffMembership?.seller?.stores?.[0]) {
      store = staffMembership.seller.stores[0];
    }
  }

  const isPending = store ? !store.isApproved : true;

  return {
    context: {
      user,
      store: store ? {
        id: store.id,
        name: store.name,
        isApproved: store.isApproved,
        commissionRate: store.commissionRate,
        ownerId: store.ownerId
      } : null,
      isPending
    },
    error: null,
    status: 200
  };
}

/**
 * Ensures the authenticated user is logged in (Customer, Seller, or Admin).
 */
export async function requireCustomer(
  req?: Request
): Promise<{ user: AuthUser | null; error: string | null; status: number }> {
  const user = await getAuthUser(req);

  if (!user) {
    return { user: null, error: 'Authentication required. Please log in.', status: 401 };
  }

  return { user, error: null, status: 200 };
}

/**
 * Creates an immutable audit log entry in the database.
 */
export async function logAdminAction(
  userId: string | null,
  action: string,
  ipAddress: string | null = null
) {
  try {
    await prisma.auditLog.create({
      data: {
        userId,
        action,
        ipAddress
      }
    });
  } catch (err) {
    console.error('Audit Log Error:', err);
  }
}

import { PrismaClient } from '@prisma/client';

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: process.env.NODE_ENV === 'development' ? ['error', 'warn'] : ['error'],
  });

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

export default prisma;
